import math

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))

    div_r = next((r for r, row in enumerate(grid) if all(v == 1 for v in row)), h // 2)
    div_c = next((c for c in range(w) if all(grid[r][c] == 1 for r in range(h))), w // 2)

    regions = [
        (0, div_r, 0, div_c),
        (0, div_r, div_c + 1, w),
        (div_r + 1, h, 0, div_c),
        (div_r + 1, h, div_c + 1, w),
    ]

    def components_of_twos(region):
        r0, r1, c0, c1 = region
        seen = set()
        comps = []
        for r in range(r0, r1):
            for c in range(c0, c1):
                if grid[r][c] != 2 or (r, c) in seen:
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                comp = []
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                        if r0 <= ny < r1 and c0 <= nx < c1 and grid[ny][nx] == 2 and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            stack.append((ny, nx))
                comps.append(comp)
        return comps

    seeds = components_of_twos(regions[0])
    if not seeds:
        return out
    seed = max(seeds, key=len)
    sr0 = min(r for r, c in seed)
    sr1 = max(r for r, c in seed) + 1
    sc0 = min(c for r, c in seed)
    sc1 = max(c for r, c in seed) + 1
    sh, sw = sr1 - sr0, sc1 - sc0
    seed_set = set(seed)

    decorations = []
    for r in range(regions[0][0], regions[0][1]):
        for c in range(regions[0][2], regions[0][3]):
            if grid[r][c] != bg and (r, c) not in seed_set:
                decorations.append((r - sr0, c - sc0, grid[r][c]))

    def scaled_positions(offset, scale):
        lo = math.floor(offset * scale)
        hi = math.floor((offset + 1) * scale) - 1
        return range(lo, hi + 1) if hi >= lo else ()

    for idx in (1, 2, 3):
        comps = components_of_twos(regions[idx])
        for comp in comps:
            tr0 = min(r for r, c in comp)
            tr1 = max(r for r, c in comp) + 1
            tc0 = min(c for r, c in comp)
            tc1 = max(c for r, c in comp) + 1
            th, tw = tr1 - tr0, tc1 - tc0
            sy, sx = th / sh, tw / sw
            flip_y = idx in (2, 3)
            flip_x = idx in (1, 3)

            for dy, dx, color in decorations:
                ys = list(scaled_positions(dy, sy))
                xs = list(scaled_positions(dx, sx))
                if flip_y:
                    ys = [th - 1 - q for q in ys]
                if flip_x:
                    xs = [tw - 1 - q for q in xs]
                for qy in ys:
                    for qx in xs:
                        y, x = tr0 + qy, tc0 + qx
                        if 0 <= y < h and 0 <= x < w and out[y][x] == bg:
                            out[y][x] = color

    return out
